sys_script_include.script:
var PatientUtils = Class.create();
PatientUtils.prototype = {
    initialize: function() {},
    //Fetch all patient details by patient ID.
    fetchpatientdetailbyid: function(id) {
        var patient = new GlideRecord('u_patient_record');
        patient.addQuery('u_number', id);
        patient.query();
        if (patient.next()) {
            return patient;
        } else {
            return "Record not found";
        }
    },
    //Check if a patient is a VIP. 
    checkvip: function(id) {
        var patient = new GlideRecord('u_patient_record');
        patient.addQuery('u_number', id);
        patient.query();
        if (patient.next()) {
            if (patient.u_vip == 'true' || patient.u_vip == true) {
                return "Patient is VIP";
            } else {
                return "Patient is not VIP";
            }
        } else {
            return "Patient Not a Found";
        }
    },
    //Calculate the patient's age.
    calage: function(id) {
        var patient = new GlideRecord('u_patient_record');
        patient.addQuery('u_number', id);
        patient.query();
        if (patient.next()) {
            var age = gs.dateDiff(patient.u_date_of_birth, gs.now(), true);
            var ageInYears = Math.floor(parseInt(age) / (60 * 60 * 24 * 365));
            return ageInYears;

        } else {
            return "Record not found"
        }

    },
    //Fetch patient's appointments.
    patientappointment: function(id) {
        var appointment = new GlideRecord('u_appointment');
        appointment.addQuery('u_patient_id', id);
        appointment.query();
        return appointment;
    },
    //Fetch patient's medications.
    patientmedication: function(id) {
        var med = new GlideRecord('u_medication');
        med.addQuery('u_patient_id', id);
        med.query();
        return med;
    },
    //Fetch patient's lab tests. 
    patientlabtest: function(id) {
        var test = new GlideRecord('u_lab_test');
        test.addQuery('u_patient_id', id);
        test.query();
        return test;
    },
	//Fetch patient's billing records.
	patientbillingrecords: function(id) {
        var bill = new GlideRecord('u_billing');
        bill.addQuery('u_patient_id', id);
        bill.query();
        return bill;
    }, 
	//Fetch patient's insurance policies. 



    type: 'PatientUtils'
};
